def main():
    hms = HospitalManagementSystem()
    added_count = 0
    failed_count = 0
    
    print(f"Starting import of {len(patient_data['patients'])} patients...")
    
    for p_dict in patient_data['patients']:
        try:
            # Create Patient object from dict
            patient = Patient(**p_dict)
            if hms.add_patient(patient):
                added_count += 1
            else:
                print(f"Failed to add patient: {p_dict.get('patient_id')}")
                failed_count += 1
        except Exception as e:
            print(f"Error processing patient {p_dict.get('patient_id')}: {e}")
            failed_count += 1
            
    print(f"Import finished. Added: {added_count}, Failed: {failed_count}")
    print(f"Current total patients: {hms.get_patients_count()}")

if __name__ == "__main__":
    main()
